#  Goal
In this tutorial you will learn how to
  * Create a tracker object.
  * Use the roiSelector function to select a ROI from a given image.
  * Track a specific region in a given image.


#  Source Code
#include <[opencv2/core/utility.hpp](https://docs.opencv.org/4.x/d1/d4e/utility_8hpp.html)>
#include <[opencv2/imgproc.hpp](https://docs.opencv.org/4.x/d1/d4f/imgproc_2include_2opencv2_2imgproc_8hpp.html)>
#include <[opencv2/tracking.hpp](https://docs.opencv.org/4.x/de/df6/contrib_2modules_2tracking_2include_2opencv2_2tracking_8hpp.html)>
#include <[opencv2/videoio.hpp](https://docs.opencv.org/4.x/dc/d3d/videoio_8hpp.html)>
#include <[opencv2/highgui.hpp](https://docs.opencv.org/4.x/d4/dd5/highgui_8hpp.html)>
#include <iostream>
#include <cstring>
using namespace [std](https://docs.opencv.org/4.x/d8/dcc/namespacestd.html);
using namespace [cv](https://docs.opencv.org/4.x/d2/d75/namespacecv.html);
int [main](https://docs.opencv.org/4.x/dc/d89/highgui__qt_8cpp.html#a0ddf1224851353fc92bfbff6f499fa97)( int argc, char** argv ){
// show help
if(argc<2){
cout<<
" Usage: tracker <video_name>\n"
" examples:\n"
" example_tracking_kcf Bolt/img/%04d.jpg\n"
" example_tracking_kcf faceocc2.webm\n"
<< endl;
return 0;
}
// declares all required variables
[Rect](https://docs.opencv.org/4.x/d2/d44/classcv_1_1Rect__.html) roi;
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) frame;
// create a tracker object
[Ptr<Tracker>](https://docs.opencv.org/4.x/dc/d84/group__core__basic.html#ga524e5e94ebf48db273a71ab275eaf5b5) tracker = TrackerKCF::create();
// set input video
std::string video = argv[1];
[VideoCapture](https://docs.opencv.org/4.x/d8/dfe/classcv_1_1VideoCapture.html) cap(video);
// get bounding box
cap >> frame;
roi=selectROI("tracker",frame);
//quit if ROI was not selected
if(roi.[width](https://docs.opencv.org/4.x/d2/d44/classcv_1_1Rect__.html#a6c16a3bce912faa4fe5be42d7f1b53fe)==0 || roi.[height](https://docs.opencv.org/4.x/d2/d44/classcv_1_1Rect__.html#a6fed06513cedd76652389e38c7b1222e)==0)
return 0;
// initialize the tracker
tracker->init(frame,roi);
// perform the tracking process
printf("Start the tracking process, press ESC to quit.\n");
for ( ;; ){
// get frame from the video
cap >> frame;
// stop the program if no more images
if(frame.rows==0 || frame.cols==0)
break;
// update the tracking result
tracker->update(frame,roi);
// draw the tracked object
rectangle( frame, roi, [Scalar](https://docs.opencv.org/4.x/d1/da0/classcv_1_1Scalar__.html)( 255, 0, 0 ), 2, 1 );
// show image with the tracked object
imshow("tracker",frame);
//quit on ESC button
if(waitKey(1)==27)break;
}
return 0;
}
