double [sum](https://docs.opencv.org/4.x/d2/de8/group__core__array.html#ga716e10a2dd9e228e4d3c95818f106722)=0;
int [cols](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#aa3e5a47585c9ef6a0842556739155e3e) = M.[cols](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#aa3e5a47585c9ef6a0842556739155e3e), [rows](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#abed816466c45234254d25bc59c31245e) = M.[rows](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#abed816466c45234254d25bc59c31245e);
if(M.[isContinuous](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#aa90cea495029c7d1ee0a41361ccecdf3)())
{
[rows](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#abed816466c45234254d25bc59c31245e) = 1;
}
for(int i = 0; i < [rows](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#abed816466c45234254d25bc59c31245e); i++)
{
const double* Mi = M.[ptr](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a8b2912f6a6f5d55a3c9a7aae9134d862)<double>(i);
for(int j = 0; j < [cols](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#aa3e5a47585c9ef6a0842556739155e3e); j++)
[sum](https://docs.opencv.org/4.x/d2/de8/group__core__array.html#ga716e10a2dd9e228e4d3c95818f106722) += std::max(Mi[j], 0.);
