{
typedef [Vec<T, 4>](https://docs.opencv.org/4.x/d6/dcf/classcv_1_1Vec.html) VT;
const float alpha_scale = (float)std::numeric_limits<T>::max(),
inv_scale = 1.f/alpha_scale;
[CV_Assert](https://docs.opencv.org/4.x/db/de0/group__core__utils.html#gaf62bcd90f70e275191ab95136d85906b)( src1.[type](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#af2d2652e552d7de635988f18a84b53e5)() == src2.[type](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#af2d2652e552d7de635988f18a84b53e5)() &&
src1.[type](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#af2d2652e552d7de635988f18a84b53e5)() == traits::Type<VT>::value &&
src1.[size](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a146f8e8dda07d1365a575ab83d9828d1)() == src2.[size](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a146f8e8dda07d1365a575ab83d9828d1)());
[Size](https://docs.opencv.org/4.x/d6/d50/classcv_1_1Size__.html) [size](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a146f8e8dda07d1365a575ab83d9828d1) = src1.[size](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a146f8e8dda07d1365a575ab83d9828d1)();
