mat.create(20, 2, [CV_32FC1](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga32ec76240e43e4c9c7b2e2785180a7e6));
n = mat.checkVector(1);
[CV_Assert](https://docs.opencv.org/4.x/db/de0/group__core__utils.html#gaf62bcd90f70e275191ab95136d85906b)(n == -1); // mat is neither a column nor a row vector
