Runs the given functor over all matrix elements in parallel. 
The operation passed as argument has to be a function pointer, a function object or a lambda(C++11).
Example 1. All of the operations below put 0xFF the first channel of all matrix elements: 
[Mat](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html) image(1920, 1080, [CV_8UC3](https://docs.opencv.org/4.x/d1/d1b/group__core__hal__interface.html#ga88c4cd9de76f678f33928ef1e3f96047));
typedef [cv::Point3_<uint8_t>](https://docs.opencv.org/4.x/df/d6c/classcv_1_1Point3__.html) Pixel;
// first. raw pointer access.
for (int r = 0; r < image.rows; ++r) {
Pixel* [ptr](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a8b2912f6a6f5d55a3c9a7aae9134d862) = image.ptr<Pixel>(r, 0);
const Pixel* ptr_end = [ptr](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a8b2912f6a6f5d55a3c9a7aae9134d862) + image.cols;
for (; [ptr](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a8b2912f6a6f5d55a3c9a7aae9134d862) != ptr_end; ++[ptr](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a8b2912f6a6f5d55a3c9a7aae9134d862)) {
[ptr](https://docs.opencv.org/4.x/d3/d63/classcv_1_1Mat.html#a8b2912f6a6f5d55a3c9a7aae9134d862)->x = 255;
}
}
// Using MatIterator. (Simple but there are a Iterator's overhead)
for (Pixel &p : [cv::Mat_<Pixel>](https://docs.opencv.org/4.x/df/dfc/classcv_1_1Mat__.html)(image)) {
p.x = 255;
}
// Parallel execution with function object.
struct Operator {
void operator ()(Pixel &pixel, const int * position) {
pixel.[x](https://docs.opencv.org/4.x/df/d6c/classcv_1_1Point3__.html#a363a0ec9e4ebce7209438cb14c29ab47) = 255;
}
};
image.forEach<Pixel>(Operator());
// Parallel execution using C++11 lambda.
image.forEach<Pixel>([](Pixel &p, const int * position) -> void {
p.x = 255;
});
